function gerarSenha(t,e,n,c){let o="abcdefghijklmnopqrstuvwxyz";if(e&&(o+="0123456789"),n&&(o+="ABCDEFGHIJKLMNOPQRSTUVWXYZ"),c&&(o+="!@#$%^&*()_+"),!o)return null;document.getElementById("botao-gerar").addEventListener("click",function(){document.querySelector(".container").classList.toggle("linha")});let r="";for(let e=0;e<t;e++)r+=o.charAt(Math.floor(Math.random()*o.length));return r}document.getElementById("botao-gerar").addEventListener("click",function(){var e=gerarSenha(document.getElementById("comprimento-senha").value,document.getElementById("incluir-numeros").checked,document.getElementById("incluir-maiusculas").checked,document.getElementById("incluir-especiais").checked);document.getElementById("senha-gerada").textContent=e||"Selecione pelo menos uma opção."});